class Firewall:

    def __init__(self):

        self.blacklist_ip = []

        self.blocked_ports = []

    def bloquer_ip(self, ip):

        self.blacklist_ip.append(ip)

    def bloquer_port(self, port):

        self.blocked_ports.append(port)

    def verifier(self, paquet):

        if paquet.ip_source in self.blacklist_ip:

            return False

        if paquet.port in self.blocked_ports:

            return False

        return True
